+      'contentId': '42',
+      'title': 'Up',
+      'parentId': '7',
+      'body': '<p>up</p>',
+      'space': 'ENG',
+      'historyComment': 'my comment',
+    })) as Map<String, dynamic>;
+    final payload = jsonDecode(body['body'] as String) as Map<String, dynamic>;
+    expect(payload['version']['message'], 'my comment');
+  });
