  Map<String, dynamic> _movePayload(String targetId) => {
        'target': {'id': targetId}
      };

  /// Builds the create-space payload with [key] and [name].
  Map<String, dynamic> _createSpacePayload(String key, String name) =>
      {'key': key, 'name': name};

