+        await client.get('127.0.0.1', server.port, '/__request_log');
+    final response = await request.close();
+    final text = await utf8.decoder.bind(response).join();
+    return (jsonDecode(text) as List<dynamic>).cast<String>();
+  } finally {
+    client.close();
+  }
+}
