+    final payload = jsonDecode(body['body'] as String) as Map<String, dynamic>;
+    expect(payload['spaceId'], '456');
+    expect(payload['status'], 'current');
+    expect(payload['title'], 'New Page');
+    expect(payload['parentId'], '7');
